using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class StructureBridgeOperations
{
    public void step(RefCounted owner,RefCounted controller,double time,double dt)
    {
        ulong started=Godot.Time.GetTicksUsec();var nodes=Map(owner,"nodes");var edges=Edges(owner);nodes.Clear();edges.Clear();owner.Set("enabled",false);var valuesById=new Settings();int iterations=2;var prototypes=Map(controller,"prototypes");var states=Map(controller,"states");foreach(var idValue in prototypes.Keys){string id=idValue.AsString();var actor=Actor(controller,id);var values=Values(controller,id,time);var state=states[id].AsGodotDictionary();if(!Get(values,"structure_enabled",false).AsBool()||!state["active"].AsBool())continue;owner.Set("enabled",true);valuesById[id]=values;iterations=Math.Max(iterations,Math.Clamp(Get(values,"structure_iterations",12).AsInt32(),2,32));var config=_settings.sample(actor,controller.Call("_local",actor,time).AsDouble());bool locked=!controller.Call("is_baking",id).AsBool()&&(config["mode"].AsInt32() is 3 or 4);config["mass"]=controller.Get("destruction").AsGodotObject().Call("mass",controller,id,state,values,config["mass"].AsDouble());if(!state.ContainsKey("structural"))state["structural"]=new Settings{["links"]=new Settings(),["supported"]=false,["island"]="",["load"]=0.0};var structural=state["structural"].AsGodotDictionary();structural["load"]=0.0;structural["supported"]=false;structural["fragments"]=new Settings();if(Get(state,"destruction_detached",false).AsBool()){foreach(var item in Get(state,"destruction_fragments",new GArray()).AsGodotArray()){var fragment=item.AsGodotDictionary();add_node(owner,controller,fragment["id"].AsString(),id,fragment,config,0,_meshes.bounds(fragment["mesh"].As<Resource>()),fragment["mass"].AsDouble(),locked||!Get(values,"debris_enabled",true).AsBool());}}else add_node(owner,controller,id,id,state,config,Get(values,"structure_role",0).AsInt32(),prototypes[id].AsGodotDictionary()["geometry"].AsGodotDictionary()["bounds"].AsAabb(),config["mass"].AsDouble(),locked);}
        foreach(var entry in valuesById){string actorId=entry.Key.AsString();var values=entry.Value.AsGodotDictionary();var state=states[actorId].AsGodotDictionary();double local=controller.Call("_local",Actor(controller,actorId),time).AsDouble();var history=state["structural"].AsGodotDictionary()["links"].AsGodotDictionary();foreach(var connection in Get(values,"structure_connections",new Settings()).AsGodotDictionary()){if(edges.Count>=1024){controller.Call("_warn","Structure: 1,024-joint budget reached.");break;}string key=connection.Key.AsString();var link=connection.Value.AsGodotDictionary();string target=Get(link,"target","").AsString();var saved=Get(history,key,new Settings{["broken"]=false,["damage"]=Get(link,"initial_damage",0).AsDouble(),["reason"]=""}).AsGodotDictionary();history[key]=saved;saved["damage"]=Math.Max(saved["damage"].AsDouble(),Get(link,"initial_damage",0).AsDouble());saved["enabled"]=Get(link,"enabled",true).AsBool();saved["load"]=0.0;saved["torque"]=0.0;saved["utilization"]=0.0;if(!prototypes.ContainsKey(target)){controller.Call("_warn","Missing structural target on "+Actor(controller,actorId).Get("display_name").AsString()+": "+target);saved["reason"]="Missing target";continue;}if(Get(link,"break_at",-1).AsDouble()>=0&&local>=link["break_at"].AsDouble()){saved["broken"]=true;saved["reason"]="Directed timeline break";}var a=endpoint(owner,actorId,Get(link,"pivot",Vector3.Zero).AsVector3());var b=endpoint(owner,target,Get(link,"target_pivot",Vector3.Zero).AsVector3());if(a.Count==0||b.Count==0){saved["reason"]="Inactive or removed attachment material";continue;}if(saved["broken"].AsBool()||!saved["enabled"].AsBool())continue;saved["reason"]="";if(!saved.ContainsKey("rest")){var poseA=nodes[a["id"]].AsGodotDictionary()["state"].AsGodotDictionary()["pose"].AsTransform3D();var poseB=nodes[b["id"]].AsGodotDictionary()["state"].AsGodotDictionary()["pose"].AsTransform3D();saved["rest"]=poseB.Basis.Orthonormalized().Inverse()*poseA.Basis.Orthonormalized();}var config=_settings.sample(Actor(controller,actorId),local);edges.Add(new Settings{["a"]=a,["b"]=b,["owner"]=actorId,["key"]=key,["link"]=link,["saved"]=saved,["linear"]=Vector3.Zero,["angular"]=Vector3.Zero,["locked"]=!controller.Call("is_baking",actorId).AsBool()&&(config["mode"].AsInt32() is 3 or 4)});}}
        if(dt>0){for(int pass=0;pass<iterations;pass++)foreach(var edge in edges)solve(owner,edge.AsGodotDictionary(),dt);foreach(var edge in edges)assess(owner,controller,edge.AsGodotDictionary(),time,dt);foreach(var entry in nodes){var node=entry.Value.AsGodotDictionary();if(node["inv"].AsDouble()==0)continue;var state=node["state"].AsGodotDictionary();var pose=state["pose"].AsTransform3D();var before=node["before"].AsTransform3D();var delta=pose.Origin-before.Origin;state["v"]=state["v"].AsVector3()+delta/(float)dt;var rotation=pose.Basis.Orthonormalized().GetRotationQuaternion()*before.Basis.Orthonormalized().GetRotationQuaternion().Inverse();double angle=Mathf.Wrap(rotation.GetAngle(),-Mathf.Pi,Mathf.Pi);if(Math.Abs(angle)>.000001)state["w"]=(state["w"].AsVector3()+rotation.GetAxis()*(float)(angle/dt)).LimitLength(30);if(delta.LengthSquared()>.0000001)state["sleep"]=0.0;_collision.place(controller.Get("world").As<RefCounted>(),entry.Key.AsString(),pose,node["config"].AsGodotDictionary()["collision"].AsBool());}}update_islands(owner,controller);owner.Set("elapsed_usec",Godot.Time.GetTicksUsec()-started);
    }
}
